fs_paste_conflict_title: "這裡已存在 {count} 個項目",
fs_paste_conflict_body: "要取代 {names} 嗎？\n\n資料夾是合併而不是清空：其中你沒有貼上的檔案會原樣保留。同名檔案會被覆寫，且無法復原。",
