library_images_capabilities: "掛載即可遊玩，或用「編輯檔案」修改其中內容——新增 DLC、替換素材或套用 backport 修補。修改會直接寫入映像檔。",

library_edit_modal_title: "編輯「{name}」",
library_edit_modal_intro: "選擇工作期間掛載到哪裡。這段時間映像檔會從 ShadowMount+ 中取出，完成後放回——在此之前遊戲不會出現在 PS5 主畫面。",
library_mount_tooltip_smp: "把此映像檔交給 ShadowMount+，由它掛載並註冊，讓你可以遊玩（唯讀）",



helper_mismatch_title: "PS5 助手為 v{payload}，而此應用程式為 v{app}",
helper_mismatch_send: "傳送助手",
helper_mismatch_body_v3: "PS5 本身無需操作：按「傳送助手」，此應用程式會把相符的助手傳送到主機。在此之前，新版本的修正和功能無法使用。",

"joberr.direct_staged_file_missing": "這次上傳其實已經完成，沒有剩餘內容可以發布——而且 PS5 上的檔案現在遺失或大小不正確。請重新上傳，並選擇「覆寫」而不是「續傳」。",
"joberr.direct_tx_corrupt": "PS5 在這次傳輸中偵測到協定損毀。請在「傳送 payload」分頁重新啟動 payload，然後再試一次。",
"joberr.direct_writer_io_error": "寫入檔案時 PS5 的可用空間不足（或外接硬碟被拔除）。請釋放目標硬碟的空間後點選「重試」——上傳會從中斷處繼續。",
"joberr.fs_delete_path_not_allowed": "PS5 拒絕存取該路徑。請使用 /data/、/user/，或已掛載的 /mnt/ext*、/mnt/usb* 路徑。",
"joberr.fs_read_path_not_allowed": "此檔案位於通常被封鎖的唯讀系統分割區。請在設定中啟用「允許下載系統檔案」，即可從 /system、/system_data 等受保護路徑下載。",
"joberr.fs_write_failed": "傳輸途中 PS5 無法寫入目標位置——通常是硬碟寫滿或外接硬碟被拔除。請檢查可用空間或重新接上硬碟，然後點選「重試」（上傳會從中斷處繼續）。",
"joberr.fs_write_failed_no_space": "目標硬碟空間已用盡（或該檔案對這個檔案系統來說太大）。請釋放 PS5 或外接硬碟的空間——或改選其他目標位置——然後點選「重試」。",
"joberr.packed_unsupported": "PS5 助手拒絕了封裝傳輸。當資料夾上傳最後只剩一個小檔案時（例如續傳一款包含大量小檔案的遊戲），舊版 payload 會出現這種情況。請將 ps5upload 更新至最新版本，在「傳送 payload」分頁重新傳送 payload，然後再試一次。",
"joberr.preflight_insufficient_space": "目標硬碟沒有足夠的可用空間存放此檔案。請釋放 PS5 的空間（設定 → 儲存空間）或改選其他目標位置，然後點選「重試」。",
"joberr.size_mismatch": "傳輸在完成前被中斷——PS5 上的某個檔案不完整，因此未被發布（若原本有舊副本，它維持不變）。這通常表示上傳過程中 PS5 進入待命模式或斷電。請讓主機保持喚醒（設定 → 系統 → 省電 → PS5 關閉前的時間），然後重新執行此項目：「續傳」只會重送缺少的檔案，「覆寫」則會重新完整複製一份。",
"joberr.ava1_stalled": "傳輸不再有進展(來源端停止傳送資料)。請重試;若反覆發生,請檢查來源磁碟機或網路共用。",
"joberr.tx_table_full": "PS5 上同時進行的傳輸過多。請等待部分傳輸完成，或重新啟動 payload。",
"joberr.zip_unsupported": "此 .zip 使用了上傳器無法串流傳輸的內容（加密、Deflate 或 Stored 以外的壓縮方式，或不安全、重複的檔案路徑）。請先在電腦上解壓縮，再上傳資料夾。",
"joberr.sevenz_unsupported": "此 .7z 使用了上傳器無法串流傳輸的壓縮方式或功能。請先在電腦上解壓縮，再上傳資料夾。",
"joberr.sevenz_unsupported_layout": "此 .7z 在同一個實心區塊中，檔案之間夾有資料夾或空檔案，上傳器無法串流傳輸這種結構。請用 7-Zip 重新封裝，或解壓縮後上傳資料夾。",
"joberr.rar_unsupported": "此 .rar 含有重複或不安全的檔案路徑，或上傳器無法串流傳輸的功能。請先在電腦上解壓縮，再上傳資料夾。",
"pkg.patch_did_not_apply": "PS5 接受了這個更新，然後什麼也沒做——遊戲仍是先前的版本。這表示主機無法將該更新與你已安裝的本體遊戲對應起來。請用 ps5upload 從與此更新搭配的本體安裝檔重新安裝本體遊戲（選擇「覆寫」），然後再次套用此更新。",
"pkglib.updateBaseUnknown.title": "此更新可能不會生效",
"pkglib.updateBaseUnknown.installAnyway": "仍然安裝",
"pkglib.updateBaseUnknown.body": "{id} 已安裝，但並非來自 ps5upload 安裝的本體安裝檔——因此 PS5 可能無法將此更新與之對應。發生這種情況時，主機會回報成功卻什麼都不改。若之後遊戲仍是舊版本，請用 ps5upload 安裝搭配的本體安裝檔（選擇「覆寫」），然後再次套用此更新。",
"pkg.patch_regressed": "重新安裝這個更新反而把它移除了——遊戲退回到了本體版本。PS5 的安裝程式會把重複安裝的更新當成要撤銷的更新。再安裝一次即可回到更新後的版本；請避免重複安裝遊戲已有的更新。",
"sdk_patch_libc": "同時修補 libc.prx",
