"arcpkg.choose": "選擇壓縮檔…",
"arcpkg.help": "適用於在任意資料夾內含有一個或多個 .pkg 檔案的 .zip、.7z 或 .rar。只解壓縮其中的安裝套件，並直接解壓縮到 PS5（這台電腦上不會解壓縮任何內容），然後逐一安裝：先裝遊戲本體，再裝更新，最後裝 DLC。支援分割 RAR（.part1.rar、.part2.rar…）：選擇第一個分割檔，並把其餘分割檔放在同一位置。RAR 需要密碼時會提示輸入；不支援有密碼的 ZIP 和 7z。",
