"install.tab.upload.lead": "先把套件複製到 PS5，再從該副本安裝。當 PS5 無法連線到這台電腦（串流安裝因網路錯誤而失敗），或想把套件留在 PS5 上以便日後不靠這台電腦重新安裝時使用。",
