"install.upload.file.title": "把套件複製到 PS5 並安裝",
"linkcard.confirm.direct": "PS5 自行從連結下載並安裝套件。開始之後不再需要這台電腦，進度顯示在 PS5 上（下載），而不是這裡。如果 PS5 無法存取該連結，應用程式會改為透過這台電腦轉送。如果 Sony 的安裝程式失敗，覆蓋安裝已安裝的遊戲可能會將其刪除。只使用你信任且有權安裝的套件連結。",
"linkcard.confirm.download": "這台電腦先把整個套件儲存到磁碟，然後安裝到 PS5。兩個步驟完成前它必須保持開機，並且需要有容納套件的可用空間。如果 Sony 的安裝程式失敗，覆蓋安裝已安裝的遊戲可能會將其刪除。只使用你信任且有權安裝的套件連結。",
"linkcard.confirm.stream": "這台電腦下載套件並立即轉送給 PS5，因此在安裝完成前它必須保持開機並連線。不會儲存到磁碟。如果 Sony 的安裝程式失敗，覆蓋安裝已安裝的遊戲可能會將其刪除。只使用你信任且有權安裝的套件連結。",
