"fpkg.image.done": "遊戲映像已寫入並讀回驗證。把它複製到 PS5 的硬碟（「上傳」），ShadowMount+ 就會掛載它。",
"fpkg.image.what": "一個檔案，複製到 PS5 的硬碟後由 ShadowMount+ 掛載並顯示在主畫面上。不會安裝任何內容。",
"fpkg.image.folderOnly": "只有這台電腦上的遊戲資料夾才能製作成遊戲映像。",
