"fpkg.make.image_title": "遊戲映像",
"fpkg.make.image_body": "放在 PS5 硬碟上的一個檔案，由 ShadowMount+ 掛載並顯示在主畫面。不安裝任何東西，而且在 PS5 封包無法執行的韌體上也能玩。",
