"fpkg.make.why_image": "這個 PS5 遊戲做成封包能安裝但在 FW {fw} 上無法執行；做成映像可以。",
"fpkg.make.why_pkg": "封包是一般的選擇：像其他遊戲一樣安裝和執行。",
