"fpkg.run.what_pkg": "封包 (.pkg)",
connection_payload_engine_unreachable: "應用程式無法連線到這台電腦上它自己的引擎，所以無法判斷助手是否已在 PS5 上啟動。這不是 PS5 的問題：視窗頂端的提示會說明原因，並可以重新啟動引擎。之後請再按一次「傳送助手」。（{error}）",
"engine_problem.missing.fix": "從防毒軟體的隔離區還原 ps5upload-engine（或允許它），或重新安裝應用程式。",
"engine_problem.missing.why": "應用程式資料夾中缺少引擎程式。安全軟體有時會將它隔離。",
"engine_problem.port.fix": "按「重新啟動引擎」。若仍不行，請在防火牆或防毒軟體中允許 ps5upload-engine，然後重新啟動應用程式。",
"engine_problem.port.why": "有程式佔用了引擎的位址（{url}）卻沒有回應：可能是該連接埠上的其他程式，或封鎖連線的安全軟體。",
"engine_problem.proxy.fix": "對本機位址（127.0.0.1）關閉 Proxy 或 VPN 工具，或在沒有 http_proxy / ALL_PROXY 設定的情況下啟動應用程式。",
"engine_problem.proxy.why": "傳給引擎的要求被送到這台電腦上設定的 Proxy，而不是引擎。",
"engine_problem.remote.fix": "檢查引擎（Docker 容器或另一台電腦）是否在執行且可透過該位址連線，或在「設定」中變更位址。",
"engine_problem.remote.why": "此應用程式設定使用的引擎（{url}）沒有回應。",
"engine_problem.restart": "重新啟動引擎",
"engine_problem.slow.fix": "按「重新啟動引擎」。過濾本機連線的防火牆或防毒軟體也可能造成此情況：請允許 ps5upload-engine。",
"engine_problem.slow.why": "引擎正在執行，但沒有回應。",
"engine_problem.stopped.fix": "按「重新啟動引擎」。如果它再次停止，「記錄」畫面會顯示原因。",
"engine_problem.stopped.why": "引擎沒有在執行：它已停止，或從未啟動。",
"engine_problem.title": "應用程式無法連線到這台電腦上的引擎",
"engine_problem.web.fix": "檢查伺服器（Docker 容器）是否在執行，然後重新載入此頁面。",
"engine_problem.web.why": "此頁面與提供它的 ps5upload 伺服器失去連線。",
gate_engine_down_body_v2: "此畫面需要應用程式的引擎，但引擎沒有回應。視窗頂端的提示會說明原因，並可以重新啟動它。",
"profile.np.body": "讓 PS5 將已登入的帳戶視為已登入 PlayStation Network，無需聯絡 Sony。部分主機功能只對已登入的帳戶開放，遙控遊玩就是其中之一。它使用 earthonion 的 np-fake-signin，在你按下按鈕時從其專案頁面取得。",
"profile.np.confirm_title": "讓此帳戶登入？",
"profile.np.failed": "登入未執行",
"profile.np.fetching": "正在取得 np-fake-signin…",
"profile.np.sending": "正在傳送到 PS5…",
"profile.np.sent": "np-fake-signin {version} 已在 PS5 上執行。重新啟動 PS5 即可完成；之後帳戶會顯示為已登入，並可開啟「設定 > 系統 > 遙控遊玩」。",
"profile.np.sign_in": "登入",
"profile.np.state_loading": "正在讀取帳戶…",
"profile.np.state_no_slot": "上方沒有名為 {user} 的帳戶，因此 np-fake-signin 會中止。請將帳戶命名為與已登入使用者相同的名稱，或為其啟用一個帳戶。",
"profile.np.state_no_user": "PS5 上沒有已登入的使用者。請登入你要使用的個人檔案，然後再回來。",
"profile.np.state_not_activated": "{user}（帳戶 {slot}）還沒有帳戶 ID。請先在上方「帳戶」中啟用它。",
"profile.np.state_ready": "就緒：{user}（帳戶 {slot}）已啟用。",
"profile.np.step_activate": "帳戶需要帳戶 ID。已連結 PSN 的帳戶本來就有；否則請在上方「帳戶」中啟用它（離線啟用）。",
"profile.np.step_run": "在 PS5 上登入該使用者後按「登入」。它執行一次後即結束。",
"profile.np.title": "登入 PlayStation Network（離線）",
