hardware_description_v2: "助手連線期間，系統資訊、運作時間和儲存空間每 5 秒自動重新整理。即時溫度和 CPU 時脈依需求讀取——按一下「讀取感測器」。零售版韌體並不提供所有讀數（例如 CPU 使用率），這些會顯示為短橫線。",
