keep_ps5_awake_mode_hint_v2: "定期重設 PS5 的自動待命計時器，使其無法進入待命模式。「上傳與安裝期間」保護長時間上傳（上傳失敗的常見原因；預設）。「連線時永遠保持」在應用程式開啟期間讓每台執行助手的主機都不進入待命模式。在任何模式下，仍可手動讓 PS5 進入待命模式。",
kernellog_categories_explainer: "所有類別一開始都會顯示。Sony 類別是主機本身的子系統，無論執行什麼 payload，在每台越獄的 PS5 上都會持續記錄日誌；它們不是由 ps5upload 造成的。取消勾選以減少雜訊。",
payloads_cached_body: "已將 {kb} KB 下載到本機快取。",
payloads_cached_title: "已快取 {id} {tag}",
payloads_description_catalog_v2: "精選的第三方 PS5 自製 payload。檢查最新版本，下載一次，然後一鍵傳送到 PS5。版本會快取在本機，因此也可以放到 USB payload 隨身碟上。",
payloads_description_send_v2: "將任何 PS5 payload 檔案——.elf、.bin、.js、.lua 或 .jar（kstuff、自訂自製載入器、瀏覽器階段漏洞利用、外掛腳本、BD-JB JAR）——傳送到你的 PS5。流程與「連線」畫面相同，只是指向你選擇的檔案。連接埠依檔案類型而定（.elf/.bin 9021、.jar 9025、.lua 9026、.js 50000）；僅在你的載入器監聽其他連接埠時才變更。",
