payloads_sent_body_pm: "連接埠 9021 沒有回應，因此 payload v{version} 改為透過 Payload Manager（:8084）啟動。請查看 PS5 上的通知。",
payloads_sent_title: "已傳送 {id} → {host}",
peripheral_drive_attachable: "此機型沒有內建光碟機；這些僅在連接外接光碟機時才有作用。",
power_telemetry_title_v2: "累計計數器",
processes_kill_payload_body: "這會終止 payload「{name}」（kstuff、etaHEN 等）。在你再次傳送之前，它提供的功能都會停止，需要它的遊戲可能無法啟動。",
processes_kill_payload_title: "停止 payload「{name}」？",
"profile.np.browser_v2": "登入需要桌面應用程式：它會取得 np-fake-signin 並傳送到 PS5，而網頁介面無法做到。",
ps5notif_empty_hint_v2: "當 ps5upload 在電視上顯示訊息（例如遙控遊玩 PIN 或開啟金手指）時，會列在這裡讓你再次查看。這不是 PS5 本身的通知面板；主機不允許我們讀取它。",
reset_confirm_body_browser: "這會清除此瀏覽器為 PS5Upload 保存的所有設定和狀態，並重新載入頁面。伺服器上引擎本身的資料（主機配對、收藏、已儲存的伺服器、降版移植函式庫、安裝歷史、日誌）不受影響，PS5 上的任何內容也不受影響。此操作無法復原。",
reset_confirm_body_v2: "這會永久刪除所有本機 PS5Upload 資料：設定、已儲存的 PS5 及其配對、收藏、已儲存的伺服器及其密碼、降版移植函式庫、安裝歷史、工作和事件、活動/佇列歷史、日誌、payload 快取和當機報告。不會觸及 PS5 上的任何內容。應用程式將重新載入為初始狀態。此操作無法復原。",
reset_hint_browser: "清除此瀏覽器為 PS5Upload 保存的所有設定和狀態並重新開始。引擎在伺服器上保存的內容（主機配對、收藏、已儲存的伺服器、降版移植函式庫、安裝歷史、日誌）不受影響，PS5 上的任何內容也不受影響。",
reset_hint_v2: "清除 PS5Upload 的所有本機痕跡並重新開始：設定、已儲存的 PS5 及其配對、收藏、已儲存的伺服器及其密碼、降版移植函式庫、安裝歷史、工作和事件、活動/佇列歷史、日誌、payload 快取和當機報告。PS5 上的任何內容都不受影響。上方的「備份 / 還原」不包括配對、收藏、伺服器密碼或降版移植函式庫。",
saves_backup_usb_tooltip_v2: "將此存檔壓縮為 zip，儲存到設定中指定的存檔路徑（PS5 上的 USB 磁碟機）。它會先複製到這台電腦、壓縮後再傳回去，因此請保持應用程式開啟；這裡的副本之後會被刪除。",
saves_description_browser: "PS5 上的存檔，每款遊戲一個項目。將存檔備份為 .zip 或還原需要桌面應用程式；在這裡你可以查看它們並開啟其資料夾。",
saves_restore_usb_tooltip_v2: "從設定中指定的存檔路徑上的最新備份還原此存檔。zip 會被複製到這台電腦、解壓縮後傳回 PS5，因此請保持應用程式開啟。會覆寫目前的存檔。",
saves_usb_menu: "USB",
saves_usb_menu_aria: "USB 備份操作",
