servers_subtitle: "你的 NAS 和伺服器（SMB、FTP、FTPS、SFTP/WebDAV）。在任何瀏覽遊戲或檔案的地方，都可以透過「瀏覽」旁的 ▾ 從中選擇。",
settings_artwork_cache_explain_v2: "遊戲封面保存在引擎執行的地方（這台電腦，或網頁版的伺服器），因此可以立即載入，而不必每次都從 PS5 讀取。它們會自動更新，當你在某台主機上安裝或解除安裝遊戲時，該主機的封面會被移除。",
settings_backup_downloaded: "已下載 {name}",
settings_backup_hint_v2: "將主題、PS5 清單、通知歷史、活動日誌和其他偏好設定打包為一個 JSON 檔案，以便在清除應用程式儲存空間後或在另一台電腦上還原。不包括主機配對、收藏、已儲存伺服器的密碼和降版移植函式庫。",
settings_backup_restored: "已還原 {count} 項設定。重新啟動應用程式以使所有變更生效。",
