settings_card_console_rest: "待命模式",
settings_card_console_connect: "連線",
auto_bringup_label: "自動啟動",
auto_bringup_hint: "當已儲存的 PS5 的載入器（elfldr，連接埠 9021）已執行而助手未執行時，應用程式會自行執行快速啟動：先執行你設定的啟動播放清單（如有），再傳送助手，然後執行自動載入播放清單。每次主機開機只執行一次；從待命模式喚醒後只重新傳送助手。載入器出現後會等待約 90 秒，讓主機自己的自動載入器先完成。預設關閉。",
bringup_auto_hint_short: "當 PS5 的載入器已執行而助手未執行時自動執行，在載入器出現約 90 秒後。每次主機開機執行一次。",
