settings_file_hint_v2: "主要偏好設定（主題、語言、引擎、存檔路徑、上傳預設值、無障礙、側邊欄）會同步到此 JSON 檔案。你可以手動編輯；編輯會在下次啟動應用程式時生效。它並不包含全部內容：要移轉所有偏好設定，請使用「備份 / 還原」。",
