status_keep_awake_tooltip_v2: "保持喚醒設為「連線時永遠保持」——應用程式開啟期間，已連線的主機不會自動進入待命模式。可在 設定 → 主機 中變更。",
update_idle_v2: "尚未檢查。開啟自動檢查後，應用程式會在啟動時於背景檢查，每天最多一次。",
upload_auto_resume_hint_browser: "如果上傳在傳輸中途中斷，會在 PS5 的助手再次回應後從中斷處繼續，重試幾次後才放棄。此頁面無法重新傳送助手本身：如果 PS5 已重新啟動，請先重新傳送助手。PS5 空間不足等嚴重問題仍會立即停止。預設開啟。",
