"profile.np.no_backup": "此帳戶帶有 np-fake-signin 的範本設定（出生日期 1983-04-12，離線成人旗標為關），而且這台 PS5 上沒有先前的副本，因此應用程式無法復原。如果 PS5 現在在開啟遊戲前要求暫時停用主機限制：設定 > 家庭和家長監控 > PS5 主機限制（若未變更，密碼為 0000），在那裡解除限制。",
