"rp_running_elsewhere": "暢玩正在 {name} 上執行",
"rp_show_here": "在此顯示",
"rp_running_elsewhere_body": "它是從另一個視窗或在本頁重新載入前啟動的，仍在執行。",
"rpg_user_title": "在 PS5 上登入一位使用者",
"rpg_user_body": "在主機上選擇你要用來遊玩的使用者。不需要有人守在畫面前，但該使用者必須保持登入。請使用沒有登入密碼的使用者：設定了密碼會在主機喚醒時阻止自動登入。",
"rpg_account_title": "為該使用者設定帳號 ID",
"rpg_account_body": "遙控遊玩透過帳號 ID 配對。已連結 PlayStation Network 的使用者本來就有；離線使用者需要在上方「使用者」中設定一個（任何 ID 都可以；請記下來，之後的存檔會與它綁定）。",
"rpg_signin_title": "讓帳戶登入 PlayStation Network（離線）",
"rpg_signin_body": "PS5 只允許已登入的帳戶使用遙控遊玩。如果主機本身的遙控遊玩設定是灰色的，請執行下方的離線登入（不會傳送任何內容給 Sony），然後重新啟動 PS5。此操作可以復原。",
"rpg_signin_fix": "前往登入",
"rpg_service_title": "開啟遙控遊玩",
"rpg_service_body": "設定 › 系統 › 遙控遊玩 › 啟用遙控遊玩。本應用程式可以替你開啟，在韌體 10.00 及更新版本上還能為這位使用者授予權限。",
"rpg_rest_title": "允許從待命模式喚醒 PS5",
"rpg_rest_body": "在 設定 › 系統 › 省電 › 待命模式可用功能 中開啟「保持連線至網際網路」和「啟用透過網路開啟 PS5」。沒有開啟的話，處於待命模式的主機無法被喚醒，網路也會在幾秒後休眠。這些只能在主機上查看。",
"rpg_pair_title": "將本應用程式與主機配對",
"rpg_pair_body": "連線 › 喚醒並登入 › 設定。只要按一下，即可將本應用程式註冊到 PS5（就像配對 PS Remote Play 應用程式一樣），並把金鑰保存在這台電腦上。串流、喚醒和登入都使用這些金鑰；重設主機或更換使用者後請重新操作。",
"rpg_play_title": "開始遊玩",
"rpg_play_body": "開啟遙控遊玩並按「開始」：如果主機處於待命模式，本應用程式會喚醒它、登入並開始串流。可以用連接到這台電腦的控制器、鍵盤或觸控來遊玩。若要改用 Sony 的 PS Remote Play 應用程式或 chiaki-ng，請在下方申請 PIN 並在那裡輸入。",
"rpg_play_fix": "開啟遙控遊玩",
"rpg_title": "設定遙控遊玩",
"rpg_progress": "已完成 {done}/{n} 個已檢查步驟",
"rpg_on_console": "請在主機上檢查",
"rpg_trouble": "如果仍然無法使用",
"rpg_t_start_q": "暢玩頁面上的「開始」是灰色的。",
"rpg_t_start_a": "本應用程式尚未與該主機配對：請完成第 6 步（連線 › 喚醒並登入 › 設定）。",
"rpg_t_pair_q": "設定配對時顯示沒有已登入且帳號已啟用的使用者。",
"rpg_t_pair_a": "第 1 和第 2 步：在 PS5 上登入一位使用者並為其設定帳號 ID，然後再試一次。",
"rpg_t_grey_q": "PS5 本身的遙控遊玩設定是灰色的。",
"rpg_t_grey_a": "該帳戶沒有登入 PlayStation Network。請執行離線登入（第 3 步）並重新啟動 PS5。",
"rpg_t_wake_q": "主機沒有被喚醒，或喚醒後停在使用者選擇畫面。",
"rpg_t_wake_a": "請在主機上檢查第 5 步。設定了登入密碼的使用者會阻止自動登入。如果主機被重設或更換了使用者，請重新設定配對（第 6 步）。",
"rpg_t_black_q": "畫面一直是黑的、卡頓，或聲音有雜音。",
"rpg_t_black_a": "讓 PS5 和這台電腦使用有線連線或 5 GHz Wi-Fi，並在遙控遊玩的設定中嘗試 720p 或 30 fps。這台電腦的防火牆必須允許本應用程式存取區域網路（遙控遊玩使用 TCP 和 UDP 連接埠 9295–9304）。在瀏覽器中請使用新版 Chrome、Edge 或 Safari：畫面需要 WebCodecs。",
"rpg_t_busy_q": "顯示 PS5 仍在結束上一次工作階段，或另一台主機正在串流。",
"rpg_t_busy_a": "一次只能串流一台主機，工作階段結束後 PS5 最多需要 30 秒。請停止另一個串流，稍等片刻，再按「開始」。",
"rpg_t_restrict_q": "離線登入後，遊戲要求停用主機限制。",
"rpg_t_restrict_a": "使用本頁的「復原登入」並重新啟動，或在 設定 › 家庭和家長監控 › PS5 主機限制 中解除限制（若未變更，密碼為 0000）。",
