"collection.send_many_body_v2": "每台 PS5 會收到它缺少的內容：遊戲的套件，或其資料夾、映像、壓縮檔，以及已有遊戲的較新更新和 DLC。套件從這台電腦串流；其餘內容上傳到「上傳並安裝」中設定的磁碟的 homebrew 資料夾。",
